from common import *
P=list(csv.DictReader((R/'analysis/points.csv').open()));C=list(csv.DictReader((R/'analysis/candidate_comparisons.csv').open()));S=list(csv.DictReader((R/'analysis/stability.csv').open()));D=list(csv.DictReader((R/'analysis/dataset_summary.csv').open()))
def table(rows,keys,labels=None):
 if not rows:return '无对应行。'
 return '| '+' | '.join(labels or keys)+' |\n| '+' | '.join(['---']*len(keys))+' |\n'+'\n'.join('| '+' | '.join(str(x.get(k,''))for k in keys)+' |'for x in rows)
total=sum(x['both_not_covered']=='True'for x in S);globaltotal=sum(x['both_new_global_not_covered']=='True'for x in S)
text=['# E196 费用邻近强控制报告','2026-11-01。继承用户详细定位授权，在E195封存之后独立冻结837点/2511完整T1批次。重测51个固定配置的102个窗口点；新增GT10/OPT-B32费用邻近预算，导航政策、模型、图、metric、GT和窗口均未改。默认E99 GT10保持。',f'初始E195粗网格有78个两窗机会，其中51个在包含其他导航的全方法两窗前沿仍未覆盖。本轮更紧控制后，{total}/51个配置在两窗均未被本轮GT10/OPT-B32覆盖；进一步纳入本轮其他已选导航后为{globaltotal}/51。未覆盖不是成功数或全局最优证明。',table(D,['dataset','candidate_window_points','covered_window_points','range_covered_points','configurations','both_not_covered','both_new_global_not_covered','both_joint_dominance','both_strict_double'],['数据','重测窗口点','被强控制覆盖点','三轮范围分离覆盖点','配置数','两窗未被强控制覆盖','两窗全方法未覆盖','两窗有联合占优参照','两窗有严格双升参照']),'## 为什么增加这轮控制','E195粗网格可能让仅增加数个命中成员的导航版本，用下一大档、召回更高的B32当质量阈值参考，产生很大的表观速度优势。这里保留全部原件，单独用原完整耗时曲线提出附近的整数L，再实测相同程序中的强控制和原导航。插值只生成预算，不代替实际Recall/QPS，也不假设Recall随L严格单调。','每个旧51配置固定不动。GT10/OPT-B32分别按旧费用估计L附近-2/0/+2以及原L+1，去重后形成837点；OPT-B32还在原L实测，返回须与原B32语义完全等价。旧B32/SQ绝对QPS没有拼入本轮比较。所有点三轮完整wall，单线程CPU15，正常Batch/路由/主搜/C/选择/扩展/合并/复制/销毁均计时。','本轮仍使用原曝光公共A/B，重复的是控制强度和费用，不是新查询泛化或跨图确认。所有预算在本轮结果前冻结，未按结果追加。','## 各数据集']
for ds in DS:
 text+=['### '+ds]
 ss=[x for x in S if x['dataset']==ds];rr=[x for x in C if x['dataset']==ds]
